1	<!doctype html>
2	<html lang="en">
3	<head>
4	  <meta charset="utf-8">
5	  <meta name="viewport" content="width=device-width, initial-scale=1">
6	  <title>Keepwell — Save a bookmark</title>
7	  <style>
8	    :root { --ink:#202722; --muted:#6b746e; --paper:#f4f1e9; --card:#fffdf8; --green:#315c4b; --lime:#dce7a7; --line:#d8d7ce; }
9	    * { box-sizing:border-box; }
10	    body { margin:0; min-height:100vh; color:var(--ink); background:var(--paper); font:15px/1.5 Inter, ui-sans-serif, system-ui, sans-serif; }
11	    button,input,textarea { font:inherit; }
12	    header { height:72px; display:flex; align-items:center; justify-content:space-between; padding:0 5vw; border-bottom:1px solid var(--line); }
13	    .brand { display:flex; gap:11px; align-items:center; font-family:Georgia,serif; font-size:23px; font-weight:700; letter-spacing:-.4px; }
14	    .mark { width:28px; height:34px; background:var(--green); border-radius:5px 5px 10px 10px; position:relative; }
15	    .mark:after { content:""; position:absolute; width:8px;height:8px;border-radius:50%;background:var(--lime);top:8px;left:10px; }
16	    .count { color:var(--muted); font-size:13px; }
17	    main { width:min(760px,90vw); margin:70px auto; }
18	    h1 { margin:0; font:700 46px/1.05 Georgia,serif; letter-spacing:-1.6px; }
19	    .lead { margin:14px 0 35px; color:var(--muted); font-size:17px; }
20	    .panel { background:var(--card); border:1px solid var(--line); border-radius:18px; box-shadow:0 15px 40px rgba(47,57,48,.07); padding:24px; }
21	    label { display:block; font-size:12px; font-weight:800; letter-spacing:.08em; text-transform:uppercase; margin-bottom:8px; }
22	    .urlrow { display:flex; gap:10px; }
23	    input,textarea { width:100%; border:1px solid #bbbdb5; border-radius:10px; background:white; padding:12px 14px; color:var(--ink); outline:none; }
24	    input:focus,textarea:focus { border-color:var(--green); box-shadow:0 0 0 3px rgba(49,92,75,.11); }
25	    button { border:0; border-radius:10px; padding:12px 19px; cursor:pointer; font-weight:750; }
26	    .primary { background:var(--green); color:white; white-space:nowrap; }
27	    .primary:hover { background:#25493b; }
28	    .primary:disabled { opacity:.55; cursor:default; }
29	    .helper { color:var(--muted); font-size:13px; margin:8px 0 0; }
30	    .editor { display:none; margin-top:24px; padding-top:24px; border-top:1px solid var(--line); }
31	    .editor.show { display:block; }
32	    .preview { display:grid; grid-template-columns:145px 1fr; gap:18px; margin-bottom:20px; }
33	    .image { min-height:126px; border-radius:12px; background:linear-gradient(145deg,#173f35,#46735c 55%,#c5d58e); color:#fff; display:flex; align-items:flex-end; padding:14px; font:700 20px/1.1 Georgia,serif; }
34	    .site { display:flex; gap:8px; align-items:center; color:var(--muted); font-size:13px; margin-bottom:10px; }
35	    .favicon { width:22px; height:22px; display:grid; place-items:center; border-radius:6px; color:white; background:#242c27; font:bold 12px Georgia,serif; }
36	    .fields { display:grid; gap:14px; }
37	    textarea { min-height:78px; resize:vertical; }
38	    .actions { display:flex; align-items:center; justify-content:flex-end; gap:12px; margin-top:20px; }
39	    .quiet { background:transparent; color:var(--muted); }
40	    .saved { display:none; align-items:center; justify-content:space-between; gap:20px; }
41	    .saved.show { display:flex; }
42	    .saved-copy { display:flex; gap:14px; align-items:center; }
43	    .check { width:38px; height:38px; flex:0 0 auto; display:grid; place-items:center; background:var(--lime); color:var(--green); border-radius:50%; font-size:20px; font-weight:900; }
44	    .saved h2 { margin:0 0 3px; font:700 23px Georgia,serif; }
45	    .saved p { margin:0; color:var(--muted); }
46	    @media(max-width:620px){ main{margin:42px auto} h1{font-size:38px}.urlrow{display:block}.urlrow button{width:100%;margin-top:10px}.preview{grid-template-columns:1fr}.image{min-height:100px}.saved{align-items:flex-start;flex-direction:column} }
47	  </style>
48	</head>
49	<body>
50	  <header>
51	    <div class="brand"><span class="mark"></span>Keepwell</div>
52	    <div class="count" id="count">0 bookmarks</div>
53	  </header>
54	  <main data-harness-ready="true">
55	    <section id="saveView">
56	      <h1>Keep what matters.</h1>
57	      <p class="lead">Paste a link and we’ll fill in the useful details.</p>
58	      <div class="panel">
59	        <label for="url">Web address</label>
60	        <div class="urlrow">
61	          <input id="url" type="url" placeholder="https://…" autocomplete="off">
62	          <button id="fetch" class="primary">Get details</button>
63	        </div>
64	        <p class="helper" id="hint">For this prototype, paste any link to preview the save flow.</p>
65	        <div class="editor" id="editor">
66	          <div class="preview">
67	            <div class="image">A calmer way to read</div>
68	            <div>
69	              <div class="site"><span class="favicon">P</span><span id="domain">papertrail.example</span></div>
70	              <div class="fields">
71	                <div><label for="title">Title</label><input id="title" value="How to build a lasting reading habit"></div>
72	                <div><label for="description">Description</label><textarea id="description">Simple ideas for making thoughtful reading part of every day.</textarea></div>
73	              </div>
74	            </div>
75	          </div>
76	          <div class="actions">
77	            <button class="quiet" id="cancel">Cancel</button>
78	            <button class="primary" id="save">Save bookmark</button>
79	          </div>
80	        </div>
81	      </div>
82	    </section>
83	    <section class="panel saved" id="savedView">
84	      <div class="saved-copy">
85	        <div class="check">✓</div>
86	        <div><h2 id="savedTitle">Bookmark saved</h2><p>Its page details are ready whenever you need it.</p></div>
87	      </div>
88	      <button class="quiet" id="again">Save another</button>
89	    </section>
90	  </main>
91	  <script>
92	    const url = document.querySelector('#url');
93	    const fetchBtn = document.querySelector('#fetch');
94	    const editor = document.querySelector('#editor');
95	    const domain = document.querySelector('#domain');
96	    const hint = document.querySelector('#hint');
97	    const saveView = document.querySelector('#saveView');
98	    const savedView = document.querySelector('#savedView');
99	    fetchBtn.onclick = () => {
100	      if (!url.value.trim()) { url.focus(); hint.textContent='Paste a link first.'; return; }
101	      try { domain.textContent = new URL(url.value.includes('://') ? url.value : 'https://' + url.value).hostname.replace(/^www\./,''); } catch { domain.textContent='the saved page'; }
102	      fetchBtn.disabled=true; fetchBtn.textContent='Getting details…';
103	      setTimeout(() => { editor.classList.add('show'); fetchBtn.textContent='Details found'; hint.textContent='We found these details on the page. You can change them before saving.'; document.querySelector('#title').focus(); }, 450);
104	    };
105	    document.querySelector('#save').onclick = () => { document.querySelector('#savedTitle').textContent='“'+document.querySelector('#title').value+'” saved'; saveView.style.display='none'; savedView.classList.add('show'); document.querySelector('#count').textContent='1 bookmark'; };
106	    document.querySelector('#cancel').onclick = () => { editor.classList.remove('show'); fetchBtn.disabled=false; fetchBtn.textContent='Get details'; hint.textContent='For this prototype, paste any link to preview the save flow.'; };
107	    document.querySelector('#again').onclick = () => { savedView.classList.remove('show'); saveView.style.display='block'; url.value=''; editor.classList.remove('show'); fetchBtn.disabled=false; fetchBtn.textContent='Get details'; document.querySelector('#count').textContent='1 bookmark'; url.focus(); };
108	    url.addEventListener('keydown', e => { if(e.key==='Enter') fetchBtn.click(); });
109	  </script>
110	</body>
111	</html>
